 XCTestCase.swift
 import XCTest
 import Foundation

 class RecoveryAdviceTest: XCTestCase {

  func testGetRecoveryAdvice() {
   // Assuming there is a function getRecoveryAdvice() that returns recovery advice for aortic dissection
   let advice = getRecoveryAdvice()

   // Check if the advice mentions to take it easy
   XCTAssertTrue(advice.lowercased().contains("don't"), "The recovery advice should include taking it easy to ensure proper healing.")
  }
 }

 // Call to the test function
 let test = RecoveryAdviceTest()
 test.testGetRecoveryAdvice()

